export const notesHtml = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Colosseum 1.2.0 — Release notes</title>\n<style>body{margin:0;background:#101114;color:#e7e5de;font:18px/1.7 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:48px 24px 96px}a{color:#f3ce4b}nav{font-size:15px;margin-bottom:48px}h1{font-size:clamp(32px,6vw,52px);line-height:1.15}h2{font-size:25px;margin-top:48px;color:#f3ce4b}li{padding:5px 0}code{overflow-wrap:anywhere;font-size:.9em}</style>\n</head><body><main><nav><a href=\"/\">Colosseum</a> / Release notes</nav><article><h1>Colosseum 1.2.0</h1>\n<p>Personal Collections, more ways to browse manga, and improvements to reading continuity, Extensions and Downloads.</p>\n<h2>Personal Collections</h2>\n<ul><li>Create private collections across supported media, add notes, and arrange titles in your own order.</li><li>Collections stay local to your profile and work without an account. Hosted sharing and gifts remain planned for 1.3.0.</li></ul>\n<h2>Manga discovery and reading</h2>\n<ul><li>Browse Completed Series, Currently Publishing, short completed series, One-shots, and manga that began in the 1990s, 2000s or 2010s.</li><li>Find existing Manhwa coverage through its dedicated category and publication filters. Manhwa series open in Chapter Mode.</li><li>Remember each series&#x27; reading language and return through Continue to the correct translation, chapter and page.</li><li>Improve Long Strip restoration and preserve numbered chapter progress when changing translations.</li></ul>\n<h2>Extensions</h2>\n<ul><li>Preview a manifest before installing from a URL.</li><li>Manage installed source instances, configuration, enabled state and removal, with manifest artwork and clearer descriptions.</li></ul>\n<h2>Downloads and Vault</h2>\n<ul><li>Keep download-backed Vault shelves up to date, including show, season and episode grouping.</li><li>Delete downloads in bulk, including download-owned Vault content, while preserving manually added Vault files.</li></ul>\n<h2>Windows integrations</h2>\n<ul><li>Optionally share local media over the local network through DLNA.</li><li>AniList is an optional experimental integration for anime episodes and manga chapters. Live sign-in and synchronization were not release-qualified; this is not a Linux integration.</li></ul>\n<h2>Local media</h2>\n<ul><li>Retry failed local playback or reopen the session without restarting Colosseum.</li><li>Open loose EPUB and comic Continue cards in their existing reader at the saved position.</li></ul>\n<h2>Availability and known limits</h2>\n<ul><li>Feria and Vinyl remain shaded and unavailable in these Windows and Linux installers, including through saved routes. Development environment opt-ins cannot enable them in shipping builds.</li><li>Android and macOS are outside this release candidate.</li><li>Some pages still lack minimize or maximize controls. Improvements in this release do not establish complete window-control coverage.</li><li>Linux updates remain manual. Debian packages use XZ compression, matching the compression method used for 1.1.9.</li></ul></article></main></body></html>\n";
